import{_ as e,o as a,c as i,a3 as s}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Roadmap | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/design/roadmap"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/design/roadmap"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/roadmap"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/roadmap"}]]},"headers":[],"relativePath":"xclang/design/roadmap.md","filePath":"en/xclang/design/roadmap.md","lastUpdated":1791227177000}'),n={name:"xclang/design/roadmap.md"};function r(d,t,o,l,h,c){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>Where xclang is going. Nothing here has a date or is a commitment. Each item is</p><ul><li><strong>planned</strong>: decided, waiting for the work;</li><li><strong>being considered</strong>: wanted, its form or its cost still open;</li><li><strong>in research</strong>: whether it can be done well is still being found out.</li></ul><p>What each release changed is in the <a href="https://github.com/clice-io/xclang/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a>.</p><h2 id="the-aim" tabindex="-1">The aim <a class="header-anchor" href="#the-aim" aria-label="Permalink to &quot;The aim&quot;">​</a></h2><p>What rustup, cross-rs and cargo-zigbuild do for Rust, for clang: one compiler for every target. The common targets come with the toolchain, as the six of today do; every other target is an archive of its own, fetched when a build needs it, with its sysroot, its prebuilt runtimes and its config file. Vendor SDKs that cannot be redistributed (Apple&#39;s, Microsoft&#39;s) are fetched from the vendor by the user, who accepts their license; xclang never redistributes them. Partly like <code>zig cc</code>, without bundling everything: what a host&#39;s toolchain does not carry is fetched, not built from bundled sources.</p><p>Every target keeps the <a href="./hermeticity">hermeticity</a> rule: a program depends at run time only on the libraries of its OS that cannot be redistributed, and links everything else statically.</p><h2 id="tiers" tabindex="-1">Tiers <a class="header-anchor" href="#tiers" aria-label="Permalink to &quot;Tiers&quot;">​</a></h2><p>Each target has a tier, as Rust&#39;s do: tier 1 is tested on a machine of the target itself, tier 2 under emulation, tier 3 compiled and linked only (<a href="./../reference/targets#tiers">tiers</a>). A target marked <strong>SDK</strong> needs a vendor SDK that the user fetches and accepts the license of; xclang&#39;s tests fetch it the same way.</p><h2 id="targets" tabindex="-1">Targets <a class="header-anchor" href="#targets" aria-label="Permalink to &quot;Targets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>target</th><th>C runtime</th><th>from</th><th>tier</th><th>status</th></tr></thead><tbody><tr><td>Linux x64, arm64</td><td>glibc 2.17</td><td>xclang</td><td>1</td><td>shipped, in every toolchain</td></tr><tr><td>Windows x64, arm64 (MinGW)</td><td>mingw-w64, UCRT</td><td>xclang</td><td>1</td><td>shipped, in every toolchain</td></tr><tr><td>macOS arm64, x64, on macOS hosts</td><td>Apple&#39;s SDK</td><td>Xcode</td><td>1</td><td>shipped, in every toolchain</td></tr><tr><td>macOS arm64, x64, from any host</td><td>Apple&#39;s SDK</td><td>the user (SDK)</td><td>1</td><td>in research</td></tr><tr><td>Windows x64, arm64 (MSVC)</td><td>Microsoft&#39;s CRT and STL, Windows SDK</td><td>the user (SDK)</td><td>1</td><td>in research</td></tr><tr><td>Windows x86 (MSVC)</td><td>Microsoft&#39;s CRT and STL, Windows SDK</td><td>the user (SDK)</td><td>1</td><td>in research</td></tr><tr><td>Windows x86 (MinGW)</td><td>mingw-w64, UCRT</td><td>xclang</td><td>1</td><td>being considered</td></tr><tr><td>Windows arm64ec</td><td>Microsoft&#39;s ARM64EC libraries</td><td>the user (SDK)</td><td>3</td><td>being considered</td></tr><tr><td>Windows 7, XP</td><td>Microsoft&#39;s CRT, linked statically, with YY-Thunks</td><td>the user (SDK)</td><td>3</td><td>in research</td></tr><tr><td>Linux x64, arm64 (musl)</td><td>musl</td><td>xclang</td><td>1</td><td>planned</td></tr><tr><td>Linux riscv64, armv7 (musl)</td><td>musl</td><td>xclang</td><td>2</td><td>being considered</td></tr><tr><td>Linux x64, arm64 with a newer glibc</td><td>glibc 2.28</td><td>xclang</td><td>1</td><td>being considered</td></tr><tr><td>Linux x86</td><td>glibc 2.17</td><td>xclang</td><td>1</td><td>being considered</td></tr><tr><td>Linux armv7 (hard float)</td><td>glibc 2.17</td><td>xclang</td><td>2</td><td>being considered</td></tr><tr><td>Linux riscv64</td><td>glibc 2.31</td><td>xclang</td><td>2</td><td>being considered</td></tr><tr><td>Linux ppc64le, s390x</td><td>glibc 2.17</td><td>xclang</td><td>2</td><td>being considered</td></tr><tr><td>Linux loongarch64</td><td>glibc 2.36</td><td>xclang</td><td>2</td><td>being considered</td></tr><tr><td>WebAssembly (<code>wasm32-wasip1</code>, <code>wasm32-wasip2</code>)</td><td>wasi-libc</td><td>xclang</td><td>1</td><td>being considered</td></tr><tr><td>Android arm64, x64, armv7</td><td>bionic</td><td>the user, from the NDK (SDK)</td><td>2</td><td>being considered</td></tr><tr><td>OpenHarmony arm64</td><td>OpenHarmony&#39;s musl</td><td>xclang</td><td>2</td><td>being considered</td></tr><tr><td>FreeBSD x64, arm64</td><td>FreeBSD 14&#39;s libc</td><td>xclang</td><td>2</td><td>being considered</td></tr><tr><td>OpenBSD, NetBSD</td><td>their libc</td><td>xclang</td><td>3</td><td>being considered</td></tr><tr><td>Bare metal: Arm Cortex-M, -R, -A, AArch64, RISC-V</td><td>picolibc</td><td>xclang</td><td>2</td><td>being considered</td></tr><tr><td>iOS, tvOS, watchOS, visionOS, their simulators</td><td>Apple&#39;s SDKs</td><td>the user, from full Xcode (SDK)</td><td>3</td><td>in research</td></tr><tr><td>Emscripten</td><td>Emscripten&#39;s own</td><td>emsdk</td><td></td><td>not a target: emsdk is its toolchain</td></tr></tbody></table><p>What sets the targets apart:</p><ul><li><strong>macOS from any host</strong>: Apple&#39;s macOS SDK comes from the Command Line Tools package on Apple&#39;s update servers, no Apple ID needed. The SDK of macOS 27 needs LLVM 23.1.3 (below).</li><li><strong>MSVC targets</strong> are to be first-class, as the MinGW ones are. The default: the VC runtime and the STL linked statically, UCRT, an OS library, dynamically (Microsoft&#39;s &quot;hybrid CRT&quot;). xclang adds compiler-rt for them: the builtins, the profile runtime and AddressSanitizer, whose runtime on Windows is a DLL. The MSVC and Windows SDK versions are pinned, and only ones the shipped clang accepts.</li><li><strong>musl</strong>: static programs that take nothing from the system they run on.</li><li><strong>A newer glibc</strong>: the same targets for programs that need what glibc 2.17 lacks (<code>-static-pie</code>, newer functions), with the same runtimes.</li><li><strong>Other Linux architectures</strong>: the oldest glibc each has; riscv64 and loongarch64 have nothing as old as 2.17. Their sanitizers are those compiler-rt supports on them.</li><li><strong>WebAssembly</strong>: <code>wasm32-wasip2</code> links with <code>wasm-component-ld</code>, a tool each host&#39;s toolchain would carry; C++ exceptions are opt-in.</li><li><strong>Android</strong>: the NDK&#39;s sysroot, with xclang&#39;s static libc++ in the NDK&#39;s ABI namespace (<code>__ndk1</code>).</li><li><strong>iOS and the rest of Apple&#39;s devices</strong>: their SDKs come only with full Xcode, downloaded with an Apple ID; that is a limit xclang cannot remove. Building their runtimes from source on demand (below) is the likely route.</li><li><strong>Windows 7 and XP</strong>: the MSVC target with the CRT linked statically and <a href="https://github.com/Chuyu-Team/YY-Thunks" target="_blank" rel="noreferrer">YY-Thunks</a> for the functions the old systems lack; MinGW with libc++ cannot reach XP. To find out how far hermeticity reaches there, not to support Windows 9x.</li></ul><h2 id="the-xclang-command" tabindex="-1">The xclang command <a class="header-anchor" href="#the-xclang-command" aria-label="Permalink to &quot;The xclang command&quot;">​</a></h2><p>Planned: <code>xclang</code>, a program in every toolchain archive that fetches what the toolchain does not carry.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xclang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x86_64-unknown-linux-musl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xclang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macos</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --accept-license</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xclang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> windows</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --accept-license</span></span></code></pre></div><ul><li><code>xclang target add</code> downloads the target&#39;s archive of the same release (its sysroot, its runtimes and compiler-rt, its config file, the licenses of its C runtime) and unpacks it into the toolchain.</li><li><code>xclang sdk fetch</code> downloads a vendor SDK from the vendor, by version and sha256, once the user accepts its license.</li><li>Each release has an index of its target archives, as rustup&#39;s channel manifests are: archive, sha256, size, tier and the SDK it needs.</li></ul><p>It is written in Rust (ureq, rustls with ring) and built for every host with xclang as its C compiler and linker, so it is xclang&#39;s first user for cargo (below). It exists, <code>cli/</code> (<a href="./../reference/xclang-command">the xclang command</a>), and is built and tested by CI, not yet in a release.</p><h2 id="xclang-for-cargo" tabindex="-1">xclang for cargo <a class="header-anchor" href="#xclang-for-cargo" aria-label="Permalink to &quot;xclang for cargo&quot;">​</a></h2><p>Planned: xclang as the C and C++ toolchain of cargo builds for other targets, the C compiler and the linker of crates with C code and of Rust&#39;s own targets, as cargo-zigbuild does with zig, with stock clang and the runtimes xclang ships. <a href="./../integrations/cargo">Rust and cargo</a> says how, from building the xclang command for every host, and for macOS and the MSVC ABI from Linux with the fetched SDKs.</p><h2 id="libc-built-on-demand" tabindex="-1">libc++ built on demand <a class="header-anchor" href="#libc-built-on-demand" aria-label="Permalink to &quot;libc++ built on demand&quot;">​</a></h2><p>Planned: libc++, libc++abi and libunwind built from source inside a CMake or Bazel build, from LLVM&#39;s runtime sources of the release (with its <a href="./patches">patches</a>), for what the prebuilt runtimes cannot be:</p><ul><li><strong>MemorySanitizer</strong>, which needs every library instrumented, libc++ too; ThreadSanitizer reports better through an instrumented libc++.</li><li><strong>Hardening and ABI options</strong>: the library&#39;s own checks of a hardening mode, libc++&#39;s ABI version 2, bounded iterators, an ABI namespace of one&#39;s own; builds without exceptions or RTTI.</li><li><strong>LTO and PGO</strong> of libc++ together with the program.</li><li><strong>Targets without prebuilt runtimes</strong>: tier 3 ones, Apple&#39;s devices.</li></ul><p>The prebuilt runtimes stay the default.</p><h2 id="build-systems" tabindex="-1">Build systems <a class="header-anchor" href="#build-systems" aria-label="Permalink to &quot;Build systems&quot;">​</a></h2><ul><li><strong>A ThinLTO link cache</strong>, shipped in 23.1.2.6: <code>XCLANG_THINLTO_CACHE</code> in the Bazel module and the CMake package keeps the code ThinLTO links generate, so a relink after a small change redoes only what changed (<a href="./../features/thinlto-cache">the ThinLTO cache</a>).</li><li><strong>More targets from CMake and Bazel</strong>, planned: both build systems would take fetched targets as they come, and the Bazel module the vendor SDKs. Its toolchains build for every target of the host&#39;s archive today (<code>--platforms=@xclang//platforms:&lt;triple&gt;</code>), the macOS ones from macOS hosts.</li></ul><h2 id="reproducibility" tabindex="-1">Reproducibility <a class="header-anchor" href="#reproducibility" aria-label="Permalink to &quot;Reproducibility&quot;">​</a></h2><ul><li><strong>Reproducible links</strong>, shipped for Bazel in 23.1.2.6: the same inputs link to the same binary wherever they are linked, debug information relative to the execution root (<code>-ffile-compilation-dir=.</code>), on macOS debug maps without the build&#39;s directory (<code>-oso_prefix</code>), on Windows no link timestamps (<a href="./../features/debugging">debugging</a>). Planned: the same for CMake builds, whose paths are the build tree&#39;s own.</li><li><strong>Immutable releases</strong>, planned: GitHub releases whose assets cannot change once published, so neither can the <code>SHA256SUMS</code> that <a href="./../integrations/cmake">CMake</a>&#39;s download checks archives against.</li></ul><h2 id="following-llvm" tabindex="-1">Following LLVM <a class="header-anchor" href="#following-llvm" aria-label="Permalink to &quot;Following LLVM&quot;">​</a></h2><ul><li><strong>LLVM 23.1.3 and 24.x</strong>, planned: each as it is released, with the <a href="./patches">patches</a> checked against it. 23.1.3 has the fix for the <code>arm64e.x1</code> architecture in the <code>.tbd</code> files of the macOS 27 SDK, which ld64.lld 23.1.2 rejects; patches/0009 carries it until then.</li><li><strong>BOLT</strong>, in research: clang and lld of the Linux hosts optimized by BOLT on top of PGO and ThinLTO.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><strong>Android&#39;s sysroot</strong>: fetched by the user from Google&#39;s NDK (only the files it needs), or redistributed by xclang.</li><li><strong>The runtimes of Apple&#39;s devices</strong>: published prebuilt, or only built on demand; Apple&#39;s license treats libraries for those platforms apart from macOS ones.</li><li><strong>A glibc other than 2.17</strong>: chosen with a named config file (<code>--config=</code>), or with a spelling of the target.</li><li><strong>Where fetched targets go</strong>: into the toolchain&#39;s directory only, or also into a directory of the user&#39;s.</li><li><strong>musl and the sanitizers</strong>: none, or a dynamically linked variant (Alpine&#39;s way) that has them.</li></ul>`,32)])])}const m=e(n,[["render",r]]);export{p as __pageData,m as default};
